import sys

def is_brute(s1, s2, s3):
    m, n = len(s1), len(s2)
    if m + n != len(s3):
        return False
    if m < n:
        s1, s2 = s2, s1
        m, n = n, m
    dp = [False] * (n + 1)
    for i in range(m + 1):
        for j in range(n + 1):
            k = i + j - 1
            if i == 0 and j == 0:
                dp[0] = True
                continue
            v = False
            if i > 0 and s1[i - 1] == s3[k] and dp[j]:
                v = True
            if j > 0 and s2[j - 1] == s3[k] and dp[j - 1]:
                v = True
            dp[j] = v
    return dp[n]

if __name__ == '__main__':
    s1 = sys.stdin.readline().rstrip()
    s2 = sys.stdin.readline().rstrip()
    s3 = sys.stdin.readline().rstrip()
    print('true' if is_brute(s1, s2, s3) else 'false')

